import {IContainer} from "@/core/platform/container/types";
import {IPipe} from "@/core/pipeline/types";

export type LogLevel =
    | "debug"
    | "info"
    | "warn"
    | "error"

/**
 * Represents a structured log entry within the logging system.
 *
 * This object is passed through formatters, processors, and transports.
 * It should remain immutable once created.
 */
export interface LogEntry {

    /**
     * Severity level of the log entry.
     */
    level: LogLevel

    /**
     * Human-readable log message.
     */
    message: string

    /**
     * Logical channel of the log entry.
     * Used for grouping logs by functional concern
     * such as "http", "domain", "security", or "performance".
     */
    channel?: string

    /**
     * Optional structured data associated with the log entry.
     * This can contain arbitrary payloads such as request data,
     * domain objects, or debugging context.
     */
    data?: any

    /**
     * Unix timestamp in milliseconds.
     * Used for ordering and time-based analysis.
     */
    timestamp: number

    /**
     * Identifier of the user session associated with the log.
     * Useful for tracing user journeys across requests.
     */
    sessionId?: string

    /**
     * Identifier of the authenticated user related to the log entry.
     * Typically corresponds to the application's user ID.
     */
    userId?: string

    /**
     * Runtime environment where the application is running
     * (e.g. "development", "production", "test").
     * Usually resolved from the build system (e.g. import.meta.env.MODE in Vite).
     */
    env?: string

    /**
     * Compile-time location identifier generated by the build system.
     * Maps to source code location via the location-map.json file.
     */
    locationId?: string

    /**
     * Name of the originating plugin or module.
     * Helps identify the source of the log entry.
     */
    module?: string

    /**
     * Version of the module that emitted the log entry.
     * Allows correlation between logs and deployed module versions.
     */
    moduleVersion?: string

    file?:string

    line?:number

    column?:number

    /**
     * Optional classification of the message type
     * (e.g. "event", "command", "query", "exception").
     */
    type?: string

    /**
     * Additional structured metadata attached to the log entry.
     * Must be serializable.
     */
    meta?: Record<string, unknown>
}


export interface ILogger {
    use(middleware: LoggerMiddleware): void
    log(
        level: LogLevel,
        message: string,
        option?: object
    ): void

    info(message: string, option?: object): void

    debug(message: string, option?: object): void

    warn(message: string, option?: object): void

    error(message: string, option?: object): void

    channel(type:string):ILogger
}

export interface LogTransport {

    write(entry: LogEntry): void

}

export type LoggerMiddleware =IPipe<LogEntry, LogEntry>

export interface LoggerStrategy {
    resolve(container: IContainer): LogTransport[];
}

export interface LogFormatter<T = unknown> {

    /**
     * Format log entry into transport-friendly output
     */
    format(entry: LogEntry): T

}




